local equippedMelee = (function()
    local api, state = {}, nil
    local STATE_KEY = "UE_EquippedMelee"

    local function call(method, ...)
        if type(method) ~= "function" then return false, "Native method is unavailable" end
        local getter, setter = getthreadidentity or getidentity, setthreadidentity or setidentity
        local identity
        if getter and setter then
            local ok, value = pcall(getter)
            if ok then identity = value; pcall(setter, 2) end
        end
        local result = table.pack(pcall(method, ...))
        if identity ~= nil then pcall(setter, identity) end
        return table.unpack(result, 1, result.n)
