    local function get(object, key)
        if type(object) ~= "table" then return nil end
        local data = rawget(object, "Data")
        if type(data) == "table" and data[key] ~= nil then return data[key] end
        local ok, value = call(object.Get, object, key)
        if ok then return value end
        return nil
    end

    local function isMelee(item)
        return type(item) == "table" and type(item.Info) == "table" and item.Info.Type == "Melee"
    end

    function api.IsEquipped(fighter, item)
        if type(fighter) ~= "table" or type(item) ~= "table" then return false end
        local equipped = fighter.EquippedItem
        if type(equipped) ~= "table" then return false end
        if equipped == item then return true end
        -- Native wrappers can be replaced while retaining the same replicated item.
        -- Compare replicated identity so a wrapper refresh does not cancel firing.
        local expected = get(item, "ObjectID")
        return expected ~= nil and get(equipped, "ObjectID") == expected
