    function api.RageItems(fighter)
        local item = type(fighter) == "table" and fighter.EquippedItem
        if type(item) ~= "table" then return nil end
        return { item }
    end

    local function encode(frame)
        local x, y, z = frame:ToOrientation()
        return { ["\0"] = frame.X, ["\1"] = frame.Y, ["\2"] = frame.Z,
            ["\3"] = x, ["\4"] = y, ["\5"] = z }
    end

    local function originOf(encoded)
        if typeof(encoded) == "CFrame" then return encoded.Position end
        if type(encoded) ~= "table" then return nil end
        local x, y, z = encoded["\0"], encoded["\1"], encoded["\2"]
        if type(x) ~= "number" or type(y) ~= "number" or type(z) ~= "number"
            or x ~= x or y ~= y or z ~= z or math.abs(x) == math.huge
            or math.abs(y) == math.huge or math.abs(z) == math.huge then return nil end
        return Vector3.new(x, y, z)
    end

    local function nearestEnemy(current, fighter, origin, range)
        local environmentID, team = get(fighter, "EnvironmentID"), get(fighter, "TeamID")
        if environmentID == nil then return nil end
        local closest, distance = nil, range
        local function consider(model, other)
            if not model or model == current.Player.Character then return end
            local otherEnvironment = get(other, "EnvironmentID") or model:GetAttribute("EnvironmentID")
            if otherEnvironment ~= environmentID then return end
            local otherTeam = get(other, "TeamID")
            if team ~= nil and otherTeam == team and not get(fighter, "TeamkillEnabled") then return end
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
            if not humanoid or humanoid.Health <= 0 or not root or not root:IsA("BasePart")
                or model:FindFirstChildOfClass("ForceField") then return end
            local separation = (root.Position - origin).Magnitude
            if separation < distance then closest, distance = root, separation end
        end
        for player, other in pairs(current.Fighters._player_to_fighter or {}) do
            if player ~= current.Player and typeof(player) == "Instance" and player:IsA("Player") then
                consider(player.Character, other)
            end
        end
        if current.Enemies then
            for _, enemy in pairs(current.Enemies.Objects or {}) do
                local model=rawget(enemy,"Model")
                local name=model and model.Name:lower():gsub("[^%a%d]","") or ""
                if not name:find("grimreaper",1,true) then consider(model,enemy) end
            end
        end
        return closest
    end

    function api.ProcessPair(item, pair)
        local current = state
        if not current or current.Closed or not current.RangeToggle.Value or not isMelee(item)
            or type(pair) ~= "table" or not current.Fighters then return pair end
        local fighter = current.Fighters.LocalFighter
        if not api.IsEquipped(fighter, item) then return pair end
        local origin = originOf(pair["\0"])
        if not origin then return pair end
        local range = math.clamp(tonumber(current.RangeOption.Value) or 10, 5, 20)
