        if not target then return pair end
        -- Preserve the remaining hit and animation data. This is the same
        -- two-origin adjustment used by Absense's Extend Melee Range feature.
        local adjusted = table.clone(pair)
        local frame = CFrame.new(target.Position) * CFrame.fromOrientation(-math.pi / 2, 0, 0)
        adjusted["\0"], adjusted["\1"] = encode(frame), encode(frame)
