    end

    function api.ProcessPacket(item, packet)
        if type(packet) ~= "table" then return packet end
        local pair = packet["\1"]
        local ok, adjusted = pcall(api.ProcessPair, item, pair)
        if not ok or adjusted == pair then return packet end
        local copy = table.clone(packet)
        copy["\1"] = adjusted
        return copy
    end

    function api.ConfigureRage(group, environment)
        group:AddLabel("Rage uses your equipped weapon or melee.", true)
        -- Legacy configs and initialization callbacks may still reference these
        -- options. Keep inert handles, without obsolete weapon-selection rows.
        local function fixed(value)
            return { Type = "Dropdown", Value = value, Values = type(value) == "table" and {} or { value },
                Multi = type(value) == "table", SetValue = function() end,
                OnChanged = function(self, callback) callback(self.Value) end }
        end
        environment.Options.ragebot_mode = fixed("equipped")
        environment.Options.ragebot_weapon = fixed("equipped")
        environment.Options.ragebot_settings = fixed({})
        environment.Options.ragebot_shoot_attempts = fixed(1)
    end

    function api.Attach(group, environment, context)
        local previous = rawget(sharedEnv, STATE_KEY)
        if type(previous) == "table" and type(previous.Close) == "function" then previous.Close() end
        local current = { Environment = environment, Player = game:GetService("Players").LocalPlayer,
            Records = {}, Closed = false, LastLoad = -math.huge }
        state = current
        sharedEnv[STATE_KEY] = current
        group:AddToggle("misc_melee_range_enabled", {
            Text = "Expanded melee hitbox", Default = false,
            Tooltip = "Extends melee attack reach using the Absense origin adjustment." })
        group:AddSlider("misc_melee_range", {
            Text = "Melee range", Default = 10, Min = 5, Max = 20, Rounding = 1, Suffix = " studs" })
        group:AddToggle("misc_melee_speed_enabled", {
            Text = "Melee speed override", Default = false,
            Tooltip = "Adjusts the equipped melee's attack cooldown; lower percentages are faster." })
        group:AddSlider("misc_melee_cooldown_percent", {
            Text = "Attack cooldown", Default = 25, Min = 0, Max = 100, Rounding = 0, Suffix = "%" })
        group:AddLabel("Lower cooldown = faster attacks. 100% = normal.", true)
        current.RangeToggle = environment.Toggles.misc_melee_range_enabled
        current.RangeOption = environment.Options.misc_melee_range
        current.SpeedToggle = environment.Toggles.misc_melee_speed_enabled
        current.SpeedOption = environment.Options.misc_melee_cooldown_percent

        local function restore(item, record)
            for name, hook in pairs(record.Methods) do
                if rawget(item, name) == hook.Wrapper then rawset(item, name, hook.RawOriginal) end
            end
            if record.ModifiedInfo and rawget(item, "Info") == record.ModifiedInfo then
                rawset(item, "Info", record.RawInfo)
            end
        end

        function current.Close()
            if current.Closed then return end
            current.Closed = true
            for item, record in pairs(current.Records) do restore(item, record) end
            table.clear(current.Records)
        end

        local function loadControllers()
            if current.Fighters then return true end
            if os.clock() - current.LastLoad < 3 then return false end
            current.LastLoad = os.clock()
            local scripts = current.Player and current.Player:FindFirstChild("PlayerScripts")
            local controllers = scripts and scripts:FindFirstChild("Controllers")
            local module = controllers and controllers:FindFirstChild("FighterController")
            local ok, value = call(require, module)
            if not ok or type(value) ~= "table" then return false end
            current.Fighters = value
            module = controllers:FindFirstChild("EnemyController")
            if module then
                ok, value = call(require, module)
                if ok and type(value) == "table" then current.Enemies = value end
            end
