                    record.RawInfo = rawget(item, "Info")
                    record.OriginalInfo = item.Info
                    record.ModifiedInfo = table.clone(item.Info)
                    rawset(item, "Info", record.ModifiedInfo)
                end
                local scale = math.clamp(tonumber(current.SpeedOption.Value) or 25, 0, 100) / 100
                for _, field in ipairs({ "AttackCooldown", "HeavyAttackCooldown" }) do
                    local original = record.OriginalInfo[field]
                    if type(original) == "number" then record.ModifiedInfo[field] = original * scale end
                end
            elseif record.ModifiedInfo then
                if rawget(item, "Info") == record.ModifiedInfo then rawset(item, "Info", record.RawInfo) end
                record.ModifiedInfo, record.OriginalInfo, record.RawInfo = nil, nil, nil
            end
        end

        for _, option in ipairs({ current.RangeToggle, current.RangeOption, current.SpeedToggle, current.SpeedOption }) do
            option:OnChanged(function() task.defer(refresh) end)
