-- BEGIN TOWER RAGE AND GUN HITBOXES
-- Render the player's moving local position while replicating a separate Rage pose.
local rageTransport = (function()
    local Transport = {}
    Transport.__index = Transport

    function Transport.new(runService, name)
        local self = setmetatable({ Service = runService, Name = name, Connections = {} }, Transport)
        runService:BindToRenderStep(name, Enum.RenderPriority.Input.Value - 1, function() self:Restore() end)
        self.Connections[1] = runService.PreSimulation:Connect(function() self:Restore() end)
        return self
    end

    function Transport:Bind(root)
        if self.Root == root then return end
        self:Release()
        self.Root = root
    end

    function Transport:BeginFrame(root)
        self:Bind(root)
        self:Restore()
        if not root or not root.Parent then return nil end
        self.Home = root.CFrame
        self.Velocity, self.Angular = root.AssemblyLinearVelocity, root.AssemblyAngularVelocity
        return self.Home
    end

    function Transport:Park(pose)
        local root = self.Root
        if not root or not root.Parent or not self.Home or not pose then return false end
        self.Parked = true
        self.ServerPose = pose
        root.CFrame = pose
        root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
        return true
    end

    function Transport:Restore()
        if not self.Parked then return end
        self.Parked = false
        local root = self.Root
        if root and root.Parent and self.Home then
            root.CFrame = self.Home
            root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = self.Velocity, self.Angular
        end
    end

    function Transport:Release()
        self:Restore()
        self.Root, self.Home, self.ServerPose = nil, nil, nil
    end

    function Transport:Destroy()
        self:Release()
        self.Service:UnbindFromRenderStep(self.Name)
        for _, connection in ipairs(self.Connections) do connection:Disconnect() end
        table.clear(self.Connections)
    end

    return Transport
end)()

-- One equipped-item attack path for players and tower NPCs.
local towerRage = (function()
    local API, Engine = {}, {}
    Engine.__index = Engine
    local TOWERS = { ["Zombie Tower"] = true, ["Gargoyle Tower"] = true }

    local function call(fn, ...)
        if type(fn) ~= "function" then return false, "missing native method" end
        local getIdentity, setIdentity = getthreadidentity or getidentity, setthreadidentity or setidentity
        local identity
        if getIdentity and setIdentity then
            local ok, value = pcall(getIdentity)
            if ok then identity = value; pcall(setIdentity, 2) end
        end
        local result = table.pack(pcall(fn, ...))
        if identity ~= nil then pcall(setIdentity, identity) end
        return table.unpack(result, 1, result.n)
    end
    local function read(object, key)
        if type(object) ~= "table" then return nil end
        local data = rawget(object, "Data")
        if type(data) == "table" and data[key] ~= nil then return data[key] end
        local ok, value = call(object.Get, object, key)
        if ok then return value end
        return nil
    end
    local function bounded(value, default, minimum, maximum)
        value = tonumber(value)
        if not value or value ~= value or math.abs(value) == math.huge then value = default end
        return math.clamp(value, minimum, maximum)
    end
    local function look(origin, target)
        local direction = target - origin
        if direction.Magnitude < 0.001 then direction = Vector3.new(0, 0, -1) end
        return CFrame.lookAt(origin, origin + direction, math.abs(direction.Unit.Y) > 0.99 and Vector3.zAxis or Vector3.yAxis)
    end
    local function sameItem(fighter, item)
        local held = fighter and fighter.EquippedItem
        if held == item then return held ~= nil end
        local id = read(item, "ObjectID")
        return id ~= nil and id == read(held, "ObjectID")
    end
    local function hazard(part, tower)
        while part and part ~= tower do
            local name = part.Name:lower()
            if name:find("kill",1,true) or name:find("oob",1,true) or name:find("lava",1,true)
                or name:find("acid",1,true) or name:find("spike",1,true) then return true end
            part = part.Parent
        end
        return false
    end

    local function npcProfile(model, native)
        local names={model and model.Name or "",native and native.Name or "",read(native,"Name") or ""}
        if model and type(model.GetAttribute)=="function" then
            for _,key in ipairs({"EnemyType","EntityType","NPCType","DisplayName"}) do
                local ok,value=pcall(model.GetAttribute,model,key)
                if ok and type(value)=="string" then names[#names+1]=value end
            end
        end
        local name=table.concat(names," "):lower():gsub("[^%a%d]","")
        return {Forbidden=name:find("grimreaper",1,true)~=nil,
            Explosive=name:find("explos",1,true)~=nil or name:find("explod",1,true)~=nil
                or name:find("bomber",1,true)~=nil or name:find("volatile",1,true)~=nil,
            Skeleton=name:find("skelet",1,true)~=nil}
    end

    function API.Create(getConfig, onStatus, dependencies)
        dependencies = dependencies or {}
        return setmetatable({ GetConfig = getConfig, OnStatus = onStatus, Clock = dependencies.Clock or os.clock,
            Native = dependencies.Native, Transport = dependencies.Transport, Random = dependencies.Random or Random.new(),
            LastLoad = -math.huge, LastScan = -math.huge, NextFire = 0, Generation = 0, Phase = "idle",
            Health = {}, HealthTargets = {}, DeathConnections = {}, ExplosionObserved = {},
            DangerZones = {}, Threats = {}, UnsafeTargets = {}, TriggerVisits = {}, LastProgress = 0,
            Stats = { Status = "Disabled", Shots = 0, MeleeAttacks = 0, Reloads = 0, Errors = 0, NativeDeclines = 0,
                Sessions = 0, DamageObserved = 0, Eliminations = 0, VoidMoves = 0, FloorVisits = 0 } }, Engine)
    end
    function Engine:Status(message)
        if self.Stats.Status == message then return end
        self.Stats.Status = message
        if self.OnStatus then pcall(self.OnStatus, message, self.Stats) end
    end
    function Engine:Load()
        if self.Native then return true end
        if self.Clock() - self.LastLoad < 2 then return false end
        self.LastLoad = self.Clock()
        local player = game:GetService("Players").LocalPlayer
        local scripts = player and player:FindFirstChild("PlayerScripts")
        local controllers = scripts and scripts:FindFirstChild("Controllers")
        if not controllers then return false end
        local function load(parent, name)
            local module = parent and parent:FindFirstChild(name)
            local ok, result = call(require, module)
            if ok then return result end
        end
        local rs = game:GetService("ReplicatedStorage")
        local remotes = rs:FindFirstChild("Remotes")
        local replication = remotes and remotes:FindFirstChild("Replication")
        local folder = replication and replication:FindFirstChild("Fighter")
