        self.Busy, self.Running, self.Target, self.Visit = false, false, nil, nil
        self.Phase, self.PhaseTarget, self.PhaseItem = "idle", nil, nil
        self.PendingRetreat,self.CoverUntil,self.LastMeleeSentAt=nil,nil,nil
        self.PoseCache=nil
        self.LocalHumanoid,self.LastLocalHealth,self.LastAttackPose=nil,nil,nil
        for _,connection in pairs(self.DeathConnections) do connection:Disconnect() end
        self.DeathConnections={}
        if self.Transport then self.Transport:Release() end
        self:Status(reason or "Disabled")
    end
    function Engine:Destroy()
        self:Stop("Menu closed")
        self.Closed = true
        if self.Transport then self.Transport:Destroy(); self.Transport = nil end
    end
    function Engine:FloorAt(position)
        if self.Map and type(self.Map.GetFloorNumberFromPosition) == "function" then
            local ok, value = call(self.Map.GetFloorNumberFromPosition,self.Map,position)
            if ok and value then return value end
        end
        local floors = self.Tower and self.Tower:FindFirstChild("Floors")
        if not floors then return nil end
        for _, floor in ipairs(floors:GetChildren()) do
            local important = floor:FindFirstChild("Important")
            if important then for _, volume in ipairs(important:GetChildren()) do
                if volume.Name == "Volume" and volume:IsA("BasePart") then
                    local p, size = volume.CFrame:PointToObjectSpace(position), volume.Size / 2
                    if math.abs(p.X)<=size.X and math.abs(p.Y)<=size.Y and math.abs(p.Z)<=size.Z then return tonumber(floor.Name) end
                end
            end end
        end
    end
    function Engine:Params(character, ground)
        local params = RaycastParams.new()
        params.FilterType, params.IgnoreWater, params.RespectCanCollide = Enum.RaycastFilterType.Exclude, true, ground == true
        local excluded = { character }
        if self.Tower then excluded[#excluded+1] = self.Tower.Entities end
        for _, name in ipairs({"ViewModels","HurtEffect"}) do
            local found=workspace:FindFirstChild(name); if found then excluded[#excluded+1]=found end
        end
        params.FilterDescendantsInstances = excluded
        return params
    end
    function Engine:TrackHealth()
        local now=self.Clock()
        for index=#self.DangerZones,1,-1 do
            if self.DangerZones[index].Until<=now then table.remove(self.DangerZones,index) end
        end
        for humanoid, old in pairs(self.Health) do
            local health = humanoid.Health
            if health < old then
                self.Stats.DamageObserved += old-health
                self.LastProgress = self.Clock()
                if old>0 and health<=0 then
                    self.Stats.Eliminations += 1
                    local target=self.HealthTargets[humanoid]
                    if self.Tower and target and target.Profile.Explosive then
                        self:RecordExplosion(humanoid,target)
                    end
                end
            end
            if humanoid.Parent then self.Health[humanoid]=health
            else
                self.Health[humanoid]=nil;self.HealthTargets[humanoid]=nil
                local connection=self.DeathConnections[humanoid]
                if connection then connection:Disconnect();self.DeathConnections[humanoid]=nil end
                self.ExplosionObserved[humanoid]=nil
            end
        end
    end
    function Engine:AddDangerZone(position, radius, duration, kind)
        if not position then return end
        self.DangerZones[#self.DangerZones+1]={Position=position,Radius=radius,Until=self.Clock()+duration,Kind=kind}
        self.DangerRevision=(self.DangerRevision or 0)+1
        if #self.DangerZones>64 then table.remove(self.DangerZones,1) end
    end
    function Engine:RecordExplosion(humanoid,target)
        local now=self.Clock()
        if now-(self.ExplosionObserved[humanoid] or -math.huge)<0.25 then return end
        self.ExplosionObserved[humanoid]=now
        self:AddDangerZone(target.Root and target.Root.Position or target.Position,24,2,"explosion")
        self:QueueCover(0.18,"Explosive enemy eliminated")
    end
    function Engine:QueueCover(duration, reason)
        self.CoverUntil=math.max(self.CoverUntil or 0,self.Clock()+duration)
        self.CoverReason=reason
        self.PendingRetreat=true
    end
    function Engine:TowerPoseSafety(position, target)
        local clearance=40
        local now=self.Clock()
        local config=self.GetConfig()
        local fighter=self.Native and self.Native.Fighters.LocalFighter
        local item=fighter and fighter.EquippedItem
        local melee=item and item.Info and item.Info.Type=="Melee"
        local minimum=melee and bounded(config.MeleeClearance,6,5,12) or 4.5
        for _,zone in ipairs(self.DangerZones) do
            if now<zone.Until and (position-zone.Position).Magnitude<zone.Radius then return false,-math.huge end
        end
        for _,threat in ipairs(self.Threats) do
            if threat.Humanoid.Health>0 then
                local distance=(position-threat.Root.Position).Magnitude
