        local blockedExplosives,forbidden=0,0
        local function consider(model, native, player)
            local humanoid = model and model:FindFirstChildOfClass("Humanoid")
            local root = model and (model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart)
            if not humanoid or not root then return end
            self.Health[humanoid] = self.Health[humanoid] or humanoid.Health
            if humanoid.Health<=0 or model:FindFirstChildOfClass("ForceField") then return end
            local profile=npcProfile(model,native)
            local target={Model=model,Humanoid=humanoid,Root=root,Native=native,Player=player,Profile=profile,Position=root.Position}
            self.HealthTargets[humanoid]=target
            if self.Tower and profile.Explosive and humanoid.Died and not self.DeathConnections[humanoid] then
                self.DeathConnections[humanoid]=humanoid.Died:Connect(function()
                    if self.Running and self.Tower then self:RecordExplosion(humanoid,target) end
                end)
            end
            if self.Tower then
                threats[#threats+1]=target
                if profile.Forbidden then forbidden+=1;return end
            end
            local floor=self.Tower and self:FloorAt(root.Position)
            count += 1
            if self.Tower and melee and profile.Explosive then blockedExplosives+=1;return end
            if (self.UnsafeTargets[model] or 0)>self.Clock() then return end
            local helmet=model.Name:lower():find("helmet",1,true)
            local part=helmet and (model:FindFirstChild("HitboxBody") or model:FindFirstChild("UpperTorso"))
                or model:FindFirstChild("HitboxHead") or model:FindFirstChild("Head")
            part=part or root
            local origin=self.ProgressPose and self.ProgressPose.Position or home.Position
            local score=(root.Position-origin).Magnitude
            -- Fallen or voided NPCs can leave their spawn floor. They still
            -- block the server's next wave, so deprioritize rather than exclude.
            if floor and self.Stats.Floor and floor~=self.Stats.Floor then score+=10000 end
            if player and (config.Priority==player or config.Priority==player.Name) then score-=100000000 end
            target.Part,target.Score=part,score
            candidates[#candidates+1]=target
        end
        if self.Tower then
            for _, model in ipairs(self.Tower.Entities:GetChildren()) do if model:IsA("Model") then consider(model) end end
        else
            local env,team=read(fighter,"EnvironmentID"),read(fighter,"TeamID")
            for player, enemy in pairs(self.Native.Fighters._player_to_fighter or {}) do
                if player~=self.Native.Player and read(enemy,"EnvironmentID")==env
                    and (team==nil or read(enemy,"TeamID")~=team or read(fighter,"TeamkillEnabled")) then
                    local entity=rawget(enemy,"Entity")
                    if read(entity,"IsInvincible")~=true then consider(player.Character,enemy,player) end
                end
            end
        end
        self.Threats=threats
        for _,candidate in ipairs(candidates) do
            local score=candidate.Score
            if self.Tower then
                for _,threat in ipairs(threats) do
                    if threat.Model~=candidate.Model and (threat.Root.Position-candidate.Root.Position).Magnitude<10 then score+=12 end
                end
                -- Stable handoffs: small distance changes must not restart an attack.
                if self.Target and candidate.Model==self.Target.Model then score-=8 end
            end
            if score<rank then best,rank=candidate,score end
        end
        self.Stats.Enemies=count
        self.Stats.ForbiddenEnemies,self.Stats.ExplosivesWaiting=forbidden,blockedExplosives
        return best
    end
    function Engine:Cooldown(item, config)
        local info=item.Info
        local value
        if info.Type=="Melee" then value=item.Name=="Knife" and info.HeavyAttackCooldown or info.AttackCooldown
        else value=item.Name=="Revolver" and info.QuickShotCooldown or info.ShootCooldown end
        return math.max(1/240,bounded(value,0.15,0,10)*bounded(config.CooldownPercent,25,10,100)/100)
    end
    function Engine:NativeReadyIn(item)
        local info=item.Info or {}
        local fields=info.Type=="Melee" and (item.Name=="Knife" and {"_heavy_attack_cooldown","_equip_cooldown"}
            or {"_attack_cooldown","_equip_cooldown"}) or {"_shoot_cooldown","_equip_cooldown","_is_revolver_quick_shooting"}
        local remaining=0
        local nativeNow=tick()
        for _,key in ipairs(fields) do
            local value=rawget(item,key)
            if type(value)=="number" then
                local delay=value-nativeNow
                if delay>0 and delay<60 then remaining=math.max(remaining,delay) end
            end
        end
        if info.Type=="Gun" then
            local ending=rawget(item,"_reload_cooldown")
            local cancel=rawget(item,"_reload_cancel_cooldown")
            local expires=rawget(item,"_reload_cancel_expiration")
            local loaded=(tonumber(read(item,"Ammo")) or 0)>0
            local canCancel=loaded and type(cancel)=="number" and type(expires)=="number"
                and nativeNow>=cancel and nativeNow<expires
            if not canCancel and type(ending)=="number" then
                local delay=ending-nativeNow
                if delay>0 and delay<60 then remaining=math.max(remaining,delay) end
            end
        end
        return remaining
    end
    function Engine:AttackPose(target, item, config)
        local info=item.Info
        if self.Tower then
            local profile=npcProfile(target.Model,target.Native)
            if profile.Forbidden or (info.Type=="Melee" and profile.Explosive) then return nil end
            local cached=self.PoseCache
            if cached and cached.Model==target.Model and cached.Item==item and cached.Revision==(self.DangerRevision or 0)
                and self.Clock()-cached.At<0.08 then
                local pose=cached.Pose+(target.Part.Position-cached.PartPosition)
                local safe=self:TowerPoseSafety(pose.Position,target)
                local eye=pose.Position+Vector3.new(0,1.5,0)
                if safe and not workspace:Raycast(eye,target.Part.Position-eye,self:Params(self.Native and self.Native.Player.Character,false)) then return pose end
            end
            local candidates={}
            local function add(position)
                local safe,clearance=self:TowerPoseSafety(position,target)
                if safe then
                    local offset=position-target.Root.Position
                    local front=offset.Unit
                    local facing=front.X*target.Root.CFrame.LookVector.X+front.Y*target.Root.CFrame.LookVector.Y+front.Z*target.Root.CFrame.LookVector.Z
                    candidates[#candidates+1]={Pose=look(position,target.Part.Position),Score=math.min(clearance,24)*2-facing}
                end
            end
            if info.Type=="Melee" then
                local reach=item.Name=="Knife" and info.HeavyAttackReach or info.AttackReach
                local distance=math.max(0.5,math.min(bounded(config and config.MeleeDistance,7,1,20),bounded(reach,6,1,50)-0.25))
                for _,height in ipairs({0.6,1.2,2.5}) do
                    for index=0,7 do
                        local angle=index*math.pi/4
                        local away=Vector3.new(math.cos(angle),height,math.sin(angle)).Unit
                        add(target.Part.Position+away*distance-Vector3.new(0,1.5,0))
                    end
                end
                add(target.Part.Position+Vector3.new(0,distance-1.5,0))
            else
                local maximum=bounded(info.RaycastDamageDropoffEndDistance,120,12,1000)
                local distance=math.min(bounded(config and config.GunDistance,36,16,80),maximum)
                for index=0,11 do
                    local angle=index*math.pi/6
                    add(target.Root.Position+Vector3.new(math.cos(angle)*distance,6,math.sin(angle)*distance))
                end
            end
            table.sort(candidates,function(a,b)return a.Score>b.Score end)
            local character=self.Native and self.Native.Player.Character
            for index=1,math.min(#candidates,3) do
                local pose=candidates[index].Pose
                local eye=pose.Position+Vector3.new(0,1.5,0)
                if not workspace:Raycast(eye,target.Part.Position-eye,self:Params(character,false)) then
                    self.PoseCache={Model=target.Model,Item=item,Revision=self.DangerRevision or 0,At=self.Clock(),Pose=pose,PartPosition=target.Part.Position}
                    return pose
                end
            end
            return nil
        end
        if info.Type=="Melee" then
            local nativeReach=item.Name=="Knife" and info.HeavyAttackReach or info.AttackReach
            nativeReach=bounded(nativeReach,6,1,50)
            local requested=bounded(config and config.MeleeDistance,7,1,20)
            local distance=math.max(0.5,math.min(requested,nativeReach-0.2))
            -- Work outward from the actual hitbox, keeping the encoded eye
            -- within native reach while the character stays above/behind it.
            local away=(-target.Root.CFrame.LookVector+Vector3.new(0,0.6,0)).Unit
            local eye=target.Part.Position+away*distance
            return look(eye-Vector3.new(0,1.5,0),target.Part.Position)
        end
        local position=target.Root.Position-target.Root.CFrame.LookVector*4+Vector3.new(0,1,0)
        return look(position,target.Part.Position)
    end
    function Engine:VoidPose(home, config)
        local distance=bounded(config.VoidDistance,100000,10000,1000000)
        local angle=self.Random:NextNumber(0,2*math.pi)
        return CFrame.new(home.Position+Vector3.new(math.cos(angle)*distance,distance,math.sin(angle)*distance))
    end
    function Engine:IdlePose(home,config)
        if config.Void or (self.Tower and (self.PendingRetreat or self.Clock()<(self.CoverUntil or 0))) then
            self.Stats.VoidMoves+=1
            return self:VoidPose(home,config)
        end
        return self.ProgressPose or home
    end
    function Engine:SendNative(item, method, target, pose, config)
        if self.Busy then return end
        if self.Tower and target then
            local profile=npcProfile(target.Model,target.Native)
            if profile.Forbidden or (item.Info.Type=="Melee" and profile.Explosive) then return end
            if pose and not self:TowerPoseSafety(pose.Position,target) then return end
        end
        if self.Tower and method~="StartReloading" then
            local remaining=self:NativeReadyIn(item)
            if remaining>0 then self.NextFire=math.max(self.NextFire,self.Clock()+remaining);return end
        end
        self.Busy=true
        self.BusySince=self.Clock()
        local generation,native=self.Generation,self.Native
        task.spawn(function()
            local ok,err=pcall(function()
                local fighter=native.Fighters.LocalFighter
                if generation~=self.Generation or not sameItem(fighter,item) then return end
                local original,temporary=item.Info,nil
                if method~="StartReloading" then
                    temporary=table.clone(original)
                    local scale=bounded(config.CooldownPercent,25,10,100)/100
                    for _,field in ipairs({"ShootCooldown","QuickShotCooldown","AttackCooldown","HeavyAttackCooldown","BurstCooldown"}) do
                        if type(original[field])=="number" and original[field]>0 then temporary[field]=math.max(1/240,original[field]*scale) end
                    end
                    rawset(item,"_ueRagePreparing",true)
                    item.Info=temporary
                end
                -- Quick-fire's wide spread was wasting tower shots at standoff range.
                local quick=not self.Tower and method=="StartShooting" and original.Type=="Gun" and item.Name=="Revolver"
                local result=table.pack(call(item[method],item,false,quick and true or nil))
                if temporary and item.Info==temporary then item.Info=original end
                if temporary then rawset(item,"_ueRagePreparing",nil) end
                if not result[1] then error(result[2]) end
                if result[2]~=true then
                    self.Stats.NativeDeclines+=1
                    self.NextFire=self.Clock()+math.max(1/120,self:NativeReadyIn(item))
                    return
                end
                local action=result[3]
                if type(action)~="string" then error("invalid native action") end
                local payload={}
                for index=4,result.n do payload[utf8.char(index-3)]=result[index] end
                local attack=action=="StartShooting" or (original.Type=="Melee" and action=="StartAiming")
                if attack then
                    if not target or not target.Part.Parent or target.Humanoid.Health<=0 then return end
                    if self.Tower and npcProfile(target.Model,target.Native).Forbidden then return end
                    if self.Tower and not self:TowerPoseSafety(pose.Position,target) then return end
                    local part=target.Part
                    local origin=pose.Position+Vector3.new(0,1.5,0)
                    local eye=look(origin,part.Position)
                    local data=type(payload["\1"])=="table" and table.clone(payload["\1"]) or {}
                    data["\0"]=native.Utility:EncodeCFrame(eye)
                    data["\1"]=native.Utility:EncodeCFrame(look(origin+eye.LookVector*0.3,part.Position))
                    data["\2"],data["\3"]=part,native.Utility:EncodeCFrame(CFrame.new())
                    payload["\1"]=data
                end
                if generation~=self.Generation or not sameItem(fighter,item) then return end
                local id,enum=read(item,"ObjectID"),native.Enums:ToEnum(action)
                if id==nil or enum==nil then error("missing item/action identity") end
                local sent,sendError=call(native.UseItem.FireServer,native.UseItem,id,enum,payload,nil)
                if not sent then error(sendError) end
                if attack then
                    self.Stats.Shots+=1
                    if self.Tower then self.LastAttackPose=pose end
                    if original.Type=="Melee" then
                        self.Stats.MeleeAttacks+=1
                        self.LastMeleeSentAt=self.Clock()
                    end
                    if self.Tower then
                        local profile=npcProfile(target.Model,target.Native)
                        self.LastTowerShotAt=self.Clock()
                        if profile.Skeleton then
                            self:AddDangerZone(pose.Position,8,0.6,"projectile")
                            self:QueueCover(0.18,"Skeleton hit - retreating to void")
                        elseif profile.Explosive then self:QueueCover(0.12,"Explosive target - retreating to void")
                        elseif original.Type=="Melee" and (self.Stats.Enemies or 0)>1 then self:QueueCover(0.04,"Swarm hit - retreating to void") end
                    end
                elseif action=="StartReloading" then self.Stats.Reloads+=1 end
            end)
            if not ok then self.Stats.Errors+=1;self.Stats.LastError=tostring(err);self:Status("Native action error: "..tostring(err)) end
            if generation==self.Generation then
                self.Busy=false
                if self.Tower and self.PendingRetreat and self.Transport and self.Transport.Home then
                    self.Phase="hidden"
                    self.ExposeAt=math.max(self.CoverUntil or 0,self.NextFire-bounded(config.SettleMS,50,16,250)/1000)
                    self.Transport:Park(self:IdlePose(self.Transport.Home,config))
                    self.PendingRetreat=false
                end
            end
        end)
    end
    function Engine:CheckComplete(duel,team)
        local scores,winning=read(duel,"Scores"),tonumber(read(duel,"ExternalDuelWinningScore"))
        if self.Tower and team and type(scores)=="table" and winning and winning>0 and (tonumber(scores[team]) or 0)>=winning then
            self.Stats.Completed=true;self:Status(self.Tower.Name.." complete — server confirmed");return true
        end
        return false
    end
    function Engine:Ground(position,character,root,humanoid)
        local hit=workspace:Raycast(position+Vector3.new(0,8,0),Vector3.new(0,-45,0),self:Params(character,true))
        if not hit or not hit.Instance:IsDescendantOf(self.Tower) or hazard(hit.Instance,self.Tower) or hit.Normal.Y<0.65 then return nil end
        return hit.Position+Vector3.new(0,humanoid.HipHeight+root.Size.Y/2+0.1,0)
    end
    function Engine:Advance(character,root,humanoid,home,config)
        local now=self.Clock()
        if now-(self.EmptySince or now)<1 or now-(self.LastVisit or -math.huge)<0.5 then return end
        local floorNumber=self.Stats.Floor
        local floors=self.Tower.Floors
        local floor=floorNumber and floors:FindFirstChild(tostring(floorNumber))
        local collection=game:GetService("CollectionService")
        local candidates=floor and floor:GetDescendants() or {}
        for tag,number in pairs({GargoyleTowerFloor15GateTrigger=15,GargoyleTowerFloor17LeverTrigger=17}) do
            if floorNumber==number then for _,p in ipairs(collection:GetTagged(tag)) do if p:IsDescendantOf(self.Tower) then candidates[#candidates+1]=p end end end
        end
        local pending=false
        local function visit(part,nextFloor)
            local point=self:Ground(part.Position,character,root,humanoid)
            if not point then return false end
            if not self:TowerPoseSafety(point,{}) then return false end
            self.Visit={Pose=look(point,point+part.CFrame.LookVector),Until=now+0.3,Floor=nextFloor}
            self.LastVisit=now;self.Stats.FloorVisits+=1
            self.Transport:Park(self.Visit.Pose)
            return true
        end
        for _,p in ipairs(candidates) do
            local trigger=p.Name=="Trigger" or collection:HasTag(p,"MobTrigger") or collection:HasTag(p,"GargoyleTowerFloor15GateTrigger") or collection:HasTag(p,"GargoyleTowerFloor17LeverTrigger")
            if p:IsA("BasePart") and trigger and not p:GetAttribute("Triggered") and not hazard(p,self.Tower) then
                pending=true
                if now-(self.TriggerVisits[p] or -math.huge)>2 and visit(p,floorNumber) then
                    self.TriggerVisits[p]=now;self:Status("Visiting floor trigger "..tostring(floorNumber or "?"));return
                end
            end
        end
        if pending then return end
        local nextFloor,number
        for _,candidate in ipairs(floors:GetChildren()) do
            local value=tonumber(candidate.Name)
            if value and value>(floorNumber or 0) and (not number or value<number) then nextFloor,number=candidate,value end
        end
        local important=nextFloor and nextFloor:FindFirstChild("Important")
        local entrance=important and important:FindFirstChild("Entrance")
        if entrance and entrance:IsA("BasePart") and visit(entrance,number) then self:Status("Advancing to floor "..number);return end
        important=floor and floor:FindFirstChild("Important")
        if important then for _,part in ipairs(important:GetDescendants()) do
            local name=part.Name:lower()
            if part:IsA("BasePart") and (name=="exit" or name=="nextfloor" or name:find("ladder",1,true)) and not hazard(part,self.Tower) then
                if visit(part,nil) then self:Status("Visiting the next-floor exit");return end
            end
        end end
        self:Status("Waiting for the next floor to load")
    end
    function Engine:Step(enabled)
        local config=self.GetConfig()
        if self.Closed or not enabled or not config.Enabled then if self.Running then self:Stop("Disabled") end;return false end
        self.Running=true
        if not self:Load() then self:Status("Waiting for game controllers");return true end
        local native=self.Native
        local fighter,duel=native.Fighters.LocalFighter,native.Duels.CurrentObject
        local map=duel and rawget(duel,"Map")
        local tower=map and rawget(map,"Model")
        if config.TowerMode and (not tower or not TOWERS[tower.Name] or not tower:FindFirstChild("Entities")) then
            if self.Duel and self:CheckComplete(self.Duel,self.TeamID) then return true end
            if self.Transport then self.Transport:Release() end
            self:Status("Waiting for Zombie / Gargoyle Tower");return true
        end
        tower=config.TowerMode and tower or nil
        local session=tostring(read(duel,"ObjectID"))..":"..tostring(read(duel,"RoundNum"))..":"..tostring(config.TowerMode)
        if self.Session~=session or self.Tower~=tower then
            self:Stop("Match detected");self.Running=true
            self.Session,self.Tower,self.Map,self.Duel=session,tower,map,duel
            self.Health,self.HealthTargets,self.DangerZones,self.Threats,self.UnsafeTargets,self.ExplosionObserved={},{},{},{},{},{}
            self.TriggerVisits,self.ProgressPose={},nil
            self.Stats.Sessions+=1;self.Stats.Completed=false;self.Stats.Floor=nil;self.LastScan=-math.huge
            self.Stats.Tower=tower and tower.Name or nil;self.LastProgress=self.Clock()
        end
        self.TeamID=read(fighter,"TeamID") or self.TeamID
        self:TrackHealth()
        if tower and self:CheckComplete(duel,self.TeamID) then if self.Transport then self.Transport:Release() end;return true end
        local character=native.Player.Character
        local root=character and character:FindFirstChild("HumanoidRootPart")
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local env=read(fighter,"EnvironmentID")
        if not fighter or not root or not humanoid or humanoid.Health<=0 or env==nil or read(duel,"Status")~="RoundStarted" then
            if self.Transport then self.Transport:Release() end
            self:Status("Waiting for a living character / round start");return true
        end
        if tower and env~=tower:GetAttribute("EnvironmentID") then self:Status("Waiting to join the tower");return true end
        if not self.Transport then self.Transport=rageTransport.new(native.RunService,"UE.Rage."..native.HttpService:GenerateGUID(false)) end
        local home=self.Transport:BeginFrame(root)
        if not home then return true end
        if self.LocalHumanoid~=humanoid then
            self.LocalHumanoid,self.LastLocalHealth=humanoid,humanoid.Health
        elseif tower and self.LastLocalHealth and humanoid.Health<self.LastLocalHealth then
            local lost=self.LastLocalHealth-humanoid.Health
            self.Stats.DamageTaken=(self.Stats.DamageTaken or 0)+lost
            local attack=self.LastAttackPose or self.Transport.ServerPose
            if attack then self:AddDangerZone(attack.Position,8,0.8,"incoming damage") end
            self.Generation+=1;self.Busy=false;self.Phase="hidden";self.LastMeleeSentAt=nil
            self:QueueCover(0.75,"Taking damage - retreating to void")
        end
        self.LastLocalHealth=humanoid.Health
        if tower then
            local floor=self:FloorAt(self.ProgressPose and self.ProgressPose.Position or home.Position)
            if floor then self.Stats.Floor=floor end
        end
        local now=self.Clock()
        if tower and (self.PendingRetreat or now<(self.CoverUntil or 0)) then
            self.PendingRetreat=false
            self.Phase="hidden"
            self.ExposeAt=math.max(self.ExposeAt or 0,self.CoverUntil or 0)
            self.LastMeleeSentAt=nil
            self.Transport:Park(self:IdlePose(home,config))
            self:Status(self.CoverReason or "Waiting in safe cover")
            return true
        end
        if self.Visit then
            if tower and not self:TowerPoseSafety(self.Visit.Pose.Position,{}) then
                self.Visit=nil;self:QueueCover(0.12,"Floor route is unsafe")
                self.Transport:Park(self:IdlePose(home,config));return true
            end
            if now<self.Visit.Until then self.Transport:Park(self.Visit.Pose);return true end
            self.ProgressPose=self.Visit.Pose
            if self.Visit.Floor then self.Stats.Floor=self.Visit.Floor end
            self.Visit=nil;self.EmptySince=now;self.LastScan=-math.huge
        end
        if now-self.LastScan>=0.08 or not self.Target or self.Target.Humanoid.Health<=0 or not self.Target.Part.Parent then
            self.Target=self:Select(home,fighter,config);self.LastScan=now
        end
        local target,item=self.Target,fighter.EquippedItem
        if tower and target and npcProfile(target.Model,target.Native).Forbidden then
            self.Target=nil;self.LastScan=-math.huge;self:QueueCover(0.12,"Avoiding Grim Reaper")
            self.Transport:Park(self:IdlePose(home,config));return true
        end
        if not target then
            self.Phase="idle";self.EmptySince=self.EmptySince or now
            if tower and not self:TowerPoseSafety((self.ProgressPose or home).Position,{}) then
                self:QueueCover(0.12,"Avoiding nearby tower danger")
            end
            self.Transport:Park(self:IdlePose(home,config))
            if tower and (self.Stats.ExplosivesWaiting or 0)>0 then self:Status("Explosive NPC remains - equip a gun")
            elseif tower and (self.Stats.Enemies or 0)>0 then self:Status("Waiting for a safe attack position")
            elseif tower and config.AutoAdvance then self:Advance(character,root,humanoid,home,config)
            else self:Status(tower and "Waiting for tower enemies" or "Waiting for an opponent") end
            return true
        end
        self.EmptySince=nil
        if not item or not item.Info or (item.Info.Type~="Gun" and item.Info.Type~="Melee") then
            self.Transport:Park(self:IdlePose(home,config));self:Status("Equip a gun or melee weapon");return true
        end
        local melee=item.Info.Type=="Melee"
        if tower and melee and npcProfile(target.Model,target.Native).Explosive then
            self.Target=nil;self.LastScan=-math.huge;self:QueueCover(0.12,"Explosive NPC - equip a gun")
            self.Transport:Park(self:IdlePose(home,config));return true
        end
        local ammo,reserve=tonumber(read(item,"Ammo")),tonumber(read(item,"AmmoReserve"))
        if not melee and ammo~=nil and ammo<=0 then
            self.Phase="hidden";self.Transport:Park(self:IdlePose(home,config))
            if reserve==0 and not read(fighter,"InfiniteAmmoReserve") then self:Status("Equipped gun is out of ammunition");return true end
            if now>=self.NextFire and not self.Busy then self.NextFire=now+0.25;self:SendNative(item,"StartReloading",nil,home,config) end
            self:Status("Reloading "..item.Name);return true
        end
        if tower and self.Phase~="attack" then
            local waitFor=math.max(self.NextFire-now,self:NativeReadyIn(item))
            local settle=bounded(config.SettleMS,50,16,250)/1000
            if waitFor>settle then
                self.Transport:Park(self:IdlePose(home,config))
                self:Status("Weapon cooldown - waiting in cover")
                return true
            end
        end
