        local point, eye, muzzle = frame(data["\3"]), frame(data["\0"]), frame(data["\1"])
        if not point or not eye or not muzzle then return data end
        local half = record.Original / 2 - Vector3.new(0.05, 0.05, 0.05)
        local p = point.Position
        local bounded = Vector3.new(math.clamp(p.X, -math.max(half.X, 0.01), math.max(half.X, 0.01)),
            math.clamp(p.Y, -math.max(half.Y, 0.01), math.max(half.Y, 0.01)),
            math.clamp(p.Z, -math.max(half.Z, 0.01), math.max(half.Z, 0.01)))
        if (bounded - p).Magnitude < 0.001 then return data end
        local target = part.CFrame:PointToWorldSpace(bounded)
        local native = self.Loader.Native
        local copy = table.clone(data)
        copy["\0"] = native.Utility:EncodeCFrame(CFrame.lookAt(eye.Position, target))
        copy["\1"] = native.Utility:EncodeCFrame(CFrame.lookAt(muzzle.Position, target))
        copy["\3"] = native.Utility:EncodeCFrame(CFrame.new(bounded))
        self.Stats.AdjustedShots += 1
        return copy
    end
    function Manager:Refresh()
