        if not self.Loader:Load() then return end
        local native = self.Loader.Native
        local fighter = native.Fighters.LocalFighter
        local item = fighter and fighter.EquippedItem
        local environmentID = towerRage.Read(fighter, "EnvironmentID")
        if not item or not item.Info or item.Info.Type ~= "Gun" or environmentID == nil then self:Restore(); return end
