            if towerNPC and model and towerRage.IsForbidden and towerRage.IsForbidden(model) then return end
            local humanoid = model and model:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then return end
            local names = config.Part == "Head" and { "HitboxHead" }
                or config.Part == "Body" and { "HitboxBody" } or { "HitboxHead", "HitboxBody" }
