                local part = model:FindFirstChild(name)
                if part and part:IsA("BasePart") and not part.CanCollide then desired[part] = true end
            end
        end
        local team = towerRage.Read(fighter, "TeamID")
        for player, enemy in pairs(native.Fighters._player_to_fighter or {}) do
            if player ~= native.Player and towerRage.Read(enemy, "EnvironmentID") == environmentID
                and (team == nil or towerRage.Read(enemy, "TeamID") ~= team) then include(player.Character) end
        end
        for _, name in ipairs({ "Zombie Tower", "Gargoyle Tower" }) do
            local tower = workspace:FindFirstChild(name)
            local entities = tower and tower:FindFirstChild("Entities")
            if entities and tower:GetAttribute("EnvironmentID") == environmentID then
                for _, model in ipairs(entities:GetChildren()) do if model:IsA("Model") then include(model,true) end end
            end
