            if not desired[part] or not part.Parent then
                if part.Parent and part.Size == record.Applied then part.Size = record.Original end
                self.Parts[part] = nil
            end
        end
        for part in pairs(desired) do
            local record = self.Parts[part]
            if not record then record = { Original = part.Size }; self.Parts[part] = record
            elseif record.Applied and part.Size ~= record.Applied then record.Original = part.Size end
