        group:AddSlider("misc_gun_hitbox_scale", { Text = "Hitbox scale", Default = 1.5, Min = 1, Max = 3, Rounding = 1, Suffix = "x" })
        group:AddDropdown("misc_gun_hitbox_part", { Text = "Hitboxes", Values = { "Head", "Body", "Both" }, Default = "Both" })
        local old = rawget(sharedEnv, "UE_GunHitboxes")
