        local manager = API.Create(function()
            return { Enabled = environment.Toggles.misc_gun_hitbox_enabled.Value,
                Scale = environment.Options.misc_gun_hitbox_scale.Value, Part = environment.Options.misc_gun_hitbox_part.Value }
        end)
        API.Manager, sharedEnv.UE_GunHitboxes = manager, manager
        if context and context.on_close_callbacks then table.insert(context.on_close_callbacks, function() manager:Close() end) end
        if group.Outer then group.Outer.Destroying:Connect(function() manager:Close() end) end
        for _, option in ipairs({ environment.Toggles.misc_gun_hitbox_enabled, environment.Options.misc_gun_hitbox_scale,
            environment.Options.misc_gun_hitbox_part }) do option:OnChanged(function() task.defer(manager.Refresh, manager) end) end
        task.spawn(function()
            while not manager.Closed do
                local ok, err = pcall(manager.Refresh, manager)
                if not ok then manager:Close(); warn("[Gun hitboxes] " .. tostring(err)); break end
