                        pc = 71
                        if not (0 < registers[2]) then
                            pc = 19
                        end
                        pc += 1
                        if pc == 72 then block = 4
                        elseif pc == 20 then block = 3
                        else error("Unmapped branch") end
                    end
                else
                    if block < 4 then
                    -- Block 3; original instruction 20.
                        registers[5] = registers[1] * 1
                        registers[5] = 0 + registers[5]
                        registers[6] = registers[2] * 1
                        block = 5
                    else
                    -- Block 4; original instruction 72.
                        registers[5] = registers[1] % 16
                        registers[6] = registers[2] % 16
                        registers[7] = captures[0][registers[5]]
                        registers[7] = registers[7][registers[6]]
                        registers[7] = registers[7] * 1
                        registers[4] = 0 + registers[7]
                        block = 6
                    end
                end
            else
                if block < 7 then
                    if block < 6 then
                    -- Block 5; original instruction 23.
                        registers[5] = registers[5] + registers[6]
                        return registers[5]
                    else
                    -- Block 6; original instruction 74.
                        registers[7] = registers[1] - registers[5]
                        registers[1] = registers[7] / 16
                        registers[7] = registers[2] - registers[6]
                        registers[2] = registers[7] / 16
                        registers[3] = registers[3] * 16
                        pc = 2
                        if not (0 < registers[1]) then
                            pc = 19
                        end
                        pc += 1
                        if pc == 3 then block = 7
                        elseif pc == 20 then block = 8
                        else error("Unmapped branch") end
                    end
                else
                    if block < 8 then
                    -- Block 7; original instruction 3.
                        pc = 71
                        if not (0 < registers[2]) then
                            pc = 19
                        end
                        pc += 1
                        if pc == 72 then block = 9
                        elseif pc == 20 then block = 8
                        else error("Unmapped branch") end
                    else
                        if block < 9 then
                        -- Block 8; original instruction 20.
                            registers[5] = registers[1] * registers[3]
                            registers[5] = registers[4] + registers[5]
                            registers[6] = registers[2] * registers[3]
                            block = 5
                        else
                        -- Block 9; original instruction 72.
                            registers[5] = registers[1] % 16
                            registers[6] = registers[2] % 16
                            registers[7] = captures[0][registers[5]]
                            registers[7] = registers[7][registers[6]]
                            registers[7] = registers[7] * registers[3]
                            registers[4] = registers[4] + registers[7]
                            block = 6
                        end
                    end
                end
            end
        end
    end
end

-- Function 8222: stateful recovery; 2 blocks.
factories[8222] = function(captures)
    return function(...)
        local registers, environment, C = Runtime.createTable(4), (Runtime.getEnvironment())
        local F
        local block = 1
        while true do
            __step(0)
            if block < 2 then
            -- Block 1; original instruction 1.
                F = factories[8566](false)
                Runtime.setEnvironment(F, environment)
                registers[1] = F
                C = captures[0]
                C[3][C[2]] = registers[1 ]
                C = captures[1]
                C[3][C[2]] = 0
                block = 2
            else
            -- Block 2; original instruction 2.
                block = 2
            end
        end
    end
end

-- Function 8223: stateful recovery; structured control flow.
factories[8223] = function(captures)
    return function(...)
        local registers, r, D = Runtime.createTable(4)
        local f, O, K = 1
        O, D = Runtime.packArguments(...)
        r = O - 0 - 1
        if r < 0 then
            r = -1
        end
        K = 0
        for o = 2, 2 + r, 1 do
            registers[o] = D[1 + K]
            K += 1
        end
        f = 2 + r
        return Runtime.unpackRange(2, f, registers)
    end
end

