factories[8564] = function(captures)
    return function(...)
        local registers, pc, C = Runtime.createTable(4), 1
        C = captures[0]
        registers[1] = C[3][C[2]]['_destroyed']
        pc = 2
        if not registers[1] then
        else
            pc = 3
        end
        pc += 1
        if pc == 3 then
            registers[1] = captures[1]
            C = registers[1]
            registers[2] = C
            registers[1] = C['change']
            registers[3] = captures[2]
            registers[1](registers[2], registers[3])
        elseif pc == 4 then
        else
            error("Unmapped branch")
        end
        return
    end
